import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/league-creation.DGW7vZUh.js";var i=JSON.parse(`{"title":"Manage Universes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/manage-universes.md","filePath":"guide/manage-universes.md"}`),a={name:`guide/manage-universes.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="manage-universes" tabindex="-1">Manage Universes <a class="header-anchor" href="#manage-universes" aria-label="Permalink to &quot;Manage Universes&quot;">​</a></h1><p>An admin&#39;s guide to universes — isolated continuity containers for your promotions. Every show, wrestler state, rivalry, and title reign belongs to one universe, so you can run parallel timelines (&quot;what if the Attitude Era never ended?&quot;), separate campaigns per friend group, or a global roster plus private test beds without data bleeding between them.</p><hr><h2 id="step-1-—-create-a-universe" tabindex="-1">Step 1 — Create a universe <a class="header-anchor" href="#step-1-—-create-a-universe" aria-label="Permalink to &quot;Step 1 — Create a universe&quot;">​</a></h2><p>Open <strong>Universes</strong> from the navigation and click <strong>Create Universe</strong>. Give it a name and pick its <strong>type</strong> — the type shapes what the universe is for (a global shared world vs a private league space).</p><p>Everything you create while a universe is active — shows, seasons, tournaments, rivalries, wrestler stats — lives inside it.</p><hr><h2 id="step-2-—-switch-between-universes" tabindex="-1">Step 2 — Switch between universes <a class="header-anchor" href="#step-2-—-switch-between-universes" aria-label="Permalink to &quot;Step 2 — Switch between universes&quot;">​</a></h2><p>The <strong>Active Universe</strong> selector in the sidebar is the master switch. Everything you see — show lists, rankings, tournaments, dashboards — filters to the selected universe. Switching is instant and safe: nothing is shared or copied, each universe is its own continuity.</p><p>Wrestler fans are tracked <strong>per universe</strong>, so the same wrestler can be a rising rookie in one universe and a reigning Icon in another.</p><hr><h2 id="step-3-—-invite-members" tabindex="-1">Step 3 — Invite members <a class="header-anchor" href="#step-3-—-invite-members" aria-label="Permalink to &quot;Step 3 — Invite members&quot;">​</a></h2><p>Universes have membership. From the Universes page, admins generate <strong>invite links</strong>:</p><ol><li>Open the invite management dialog and generate a link for the member type you want (player, booker, …).</li><li>Share the link — it opens a <strong>Join Universe</strong> page where the visitor creates (or links) an account and submits a join request atomically.</li><li>Approve join requests from the same dialog.</li></ol><p><img src="/screenshots/league-creation.png" alt="Invite management"></p><p>Members only see the universes they belong to — the universe selector lists accessible universes, not all of them.</p><hr><h2 id="step-4-—-scope-the-content" tabindex="-1">Step 4 — Scope the content <a class="header-anchor" href="#step-4-—-scope-the-content" aria-label="Permalink to &quot;Step 4 — Scope the content&quot;">​</a></h2><p>Each universe carries its own content switches:</p><ul><li><strong>Expansion settings</strong> — which content sets are active in this universe, independent of other universes (see <a href="./admin-getting-started.html">Admin Getting Started</a> for expansions).</li><li><strong>Wrestler exclusions</strong> — bar specific wrestlers from a universe&#39;s draft pools and eligibility.</li></ul><hr><h2 id="step-5-—-back-it-up-or-take-it-with-you" tabindex="-1">Step 5 — Back it up or take it with you <a class="header-anchor" href="#step-5-—-back-it-up-or-take-it-with-you" aria-label="Permalink to &quot;Step 5 — Back it up or take it with you&quot;">​</a></h2><p>The <strong>Export/Restore Images</strong> tools on the Universes page handle universe artwork for backups and moves. For full data, <strong>Export Universe Data</strong> produces a portable dump of the universe&#39;s content — useful for archiving a completed season&#39;s continuity or sharing a setup with another install.</p><hr><h2 id="when-to-use-more-than-one-universe" tabindex="-1">When to use more than one universe <a class="header-anchor" href="#when-to-use-more-than-one-universe" aria-label="Permalink to &quot;When to use more than one universe&quot;">​</a></h2><ul><li><strong>Test changes safely</strong> — try a new ruleset in a sandbox universe before touching your main continuity.</li><li><strong>Separate friend groups</strong> — each league table gets its own universe so standings and histories never mix.</li><li><strong>Alternate timelines</strong> — branch a promotion at a dramatic moment and run both futures.</li></ul><blockquote><p>💡 <strong>Keep the number sane.</strong> Every universe multiplies the states the game tracks per wrestler. Most tables run two or three: main, sandbox, and (if leagues are in play) one per league.</p></blockquote><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./admin-getting-started.html">Admin Getting Started</a> — expansions and global settings.</li><li><a href="./run-a-league.html">Run a League</a> — the multiplayer mode that usually motivates a new universe.</li><li>The auto-generated <a href="./admin.html">Admin Overview</a> documents every admin screen.</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};